package com.qboix.app;
import android.app.Activity;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.view.Gravity;import android.view.View;import android.widget.*;import org.json.*;import java.util.*;import java.text.*;
public class PerformanceAnalyticsActivity extends Activity{
 int GOLD=Color.rgb(215,181,91),BLACK=Color.rgb(9,9,13),CARD=Color.rgb(27,27,34),WHITE=Color.WHITE,GREY=Color.rgb(165,165,175),BLUE=Color.rgb(52,136,255),GREEN=Color.rgb(55,190,125);boolean miles=false;LinearLayout body;ArrayList<JSONObject> runs=new ArrayList<>();
 public void onCreate(Bundle b){super.onCreate(b);JSONArray a=WorkoutStore.getRunSessions(this);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)runs.add(o);}Collections.sort(runs,Comparator.comparingLong(o->o.optLong("savedAt",0)));render();}
 void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BLACK);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(18),dp(14),dp(18),dp(10));bar.addView(t("Q-BOIX / ANALYTICS",GOLD,20,true),new LinearLayout.LayoutParams(0,-2,1));Button toggle=new Button(this);toggle.setText(miles?"MILES":"KILOMETRES");toggle.setTextColor(BLACK);toggle.setTextSize(10);toggle.setOnClickListener(v->{miles=!miles;render();});bar.addView(toggle);root.addView(bar);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setPadding(dp(18),dp(8),dp(18),dp(28));body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
 double total=0,longest=0,best=0;int seconds=0;for(JSONObject o:runs){double d=o.optDouble("distanceMeters",0),p=o.optDouble("averagePaceSecondsPerKm",0);total+=d;longest=Math.max(longest,d);seconds+=o.optInt("elapsedSeconds",0);if(p>0&&(best==0||p<best))best=p;}
 head("YOUR PERFORMANCE");sub(runs.size()+" GPS RUNS RECORDED");stats(new String[]{dist(total),time(seconds),pace(best),dist(longest)},new String[]{"DISTANCE","RUN TIME","BEST PACE","LONGEST RUN"});
 head("DISTANCE PROGRESS");sub("DISTANCE PER RECENT RUN");ArrayList<Double>d=new ArrayList<>();int start=Math.max(0,runs.size()-10);for(int i=start;i<runs.size();i++)d.add(runs.get(i).optDouble("distanceMeters",0)/(miles?1609.344:1000));chart(d,BLUE,miles?"miles":"km",false);
 head("PACE TREND");sub("AVERAGE PACE • LOWER IS FASTER");ArrayList<Double>p=new ArrayList<>();for(int i=start;i<runs.size();i++){double x=runs.get(i).optDouble("averagePaceSecondsPerKm",0);if(x>0)p.add(x*(miles?1.609344:1));}chart(p,GREEN,miles?"min/mile":"min/km",true);
 head("TRAINING SUMMARY");info("Total distance",dist(total));info("Total running time",time(seconds));info("Longest run",dist(longest));info("Best average pace",pace(best));info("Fartlek sessions",String.valueOf(WorkoutStore.getFartlekSessions(this).length()));
 head("LATEST GPS ROUTE");if(runs.isEmpty())sub("Complete a GPS run to unlock your charts and route plot.");else{JSONObject last=runs.get(runs.size()-1);JSONArray route=last.optJSONArray("route");if(route==null||route.length()<2)sub("No route points were saved for the latest run.");else{body.addView(new Route(route),new LinearLayout.LayoutParams(-1,dp(220)));}}
 if(runs.isEmpty()){head("GET STARTED");sub("Your distance charts, pace trends and training totals will appear after your first saved GPS run.");}setContentView(root);}
 void head(String s){TextView v=t(s,GOLD,14,true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(22);p.bottomMargin=dp(8);body.addView(v,p);}void sub(String s){TextView v=t(s,GREY,11,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(v,p);}
 void stats(String[] v,String[] n){for(int i=0;i<4;i+=2){LinearLayout row=new LinearLayout(this);for(int j=i;j<i+2;j++){LinearLayout c=panel();c.setOrientation(1);c.setPadding(dp(12),dp(14),dp(8),dp(14));c.addView(t(v[j],GOLD,18,true));c.addView(t(n[j],GREY,9,true));LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(0,-2,1);q.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(c,q);}body.addView(row);}}
 void info(String a,String b){LinearLayout r=panel();r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(12),dp(12),dp(12),dp(12));r.addView(t(a,GREY,12,false),new LinearLayout.LayoutParams(0,-2,1));r.addView(t(b,WHITE,13,true));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(6);body.addView(r,p);}
 void chart(ArrayList<Double> v,int color,String unit,boolean paceChart){LinearLayout c=panel();c.setPadding(dp(10),dp(12),dp(10),dp(8));if(v.isEmpty())c.addView(t("Not enough recorded data yet.",GREY,11,false));else c.addView(new Plot(v,color,unit,paceChart),new LinearLayout.LayoutParams(-1,dp(185)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(5);body.addView(c,p);}
 class Plot extends View{ArrayList<Double> v;int color;String unit;boolean paceChart;Paint p=new Paint(3);Plot(ArrayList<Double>a,int c,String u,boolean pc){super(PerformanceAnalyticsActivity.this);v=a;color=c;unit=u;paceChart=pc;}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),l=dp(30),r=w-dp(10),top=dp(18),bottom=h-dp(25);p.setColor(Color.DKGRAY);for(int i=0;i<4;i++){float y=top+(bottom-top)*i/3;c.drawLine(l,y,r,y,p);}double min=Collections.min(v),max=Collections.max(v);if(max==min)max=min+1;Path path=new Path();for(int i=0;i<v.size();i++){float x=l+(r-l)*(v.size()==1?.5f:(float)i/(v.size()-1));float y=paceChart?top+(float)((v.get(i)-min)/(max-min))*(bottom-top):bottom-(float)((v.get(i)-min)/(max-min))*(bottom-top);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);p.setColor(color);c.drawCircle(x,y,dp(4),p);}p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setColor(GREY);p.setTextSize(dp(9));c.drawText(unit,l,dp(12),p);c.drawText("Old",l,bottom+dp(17),p);c.drawText("Recent",r-dp(38),bottom+dp(17),p);}}
 class Route extends View{JSONArray a;Paint p=new Paint(3);Route(JSONArray x){super(PerformanceAnalyticsActivity.this);a=x;}protected void onDraw(Canvas c){double minA=90,maxA=-90,minO=180,maxO=-180;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null){double la=o.optDouble("lat"),lo=o.optDouble("lon");minA=Math.min(minA,la);maxA=Math.max(maxA,la);minO=Math.min(minO,lo);maxO=Math.max(maxO,lo);}}if(maxA==minA||maxO==minO)return;float pad=dp(18);Path path=new Path();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;float x=pad+(float)((o.optDouble("lon")-minO)/(maxO-minO))*(getWidth()-2*pad),y=getHeight()-pad-(float)((o.optDouble("lat")-minA)/(maxA-minA))*(getHeight()-2*pad);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setColor(CARD);c.drawRoundRect(0,0,getWidth(),getHeight(),dp(12),dp(12),p);p.setColor(BLUE);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}}
 String dist(double m){return String.format(Locale.getDefault(),"%.2f %s",m/(miles?1609.344:1000),miles?"mi":"km");}String pace(double s){if(s<=0)return "--:--";int n=(int)Math.round(s*(miles?1.609344:1));return String.format(Locale.getDefault(),"%d:%02d /%s",n/60,n%60,miles?"mi":"km");}String time(int s){return String.format(Locale.getDefault(),"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);}
 TextView t(String s,int c,float z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextColor(c);v.setTextSize(z);if(b)v.setTypeface(null,1);return v;}LinearLayout panel(){LinearLayout l=new LinearLayout(this);GradientDrawable d=new GradientDrawable();d.setColor(CARD);d.setCornerRadius(dp(13));l.setBackground(d);return l;}int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
}